const date=z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine(v=>!Number.isNaN(Date.parse(v))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v,'Invalid calendar date');
const time=z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/,'Use a 24-hour HH:mm time');
const schemas={
 volunteerShifts:z.object({name,date,startTime:time,endTime:time,location:short,capacity:z.number().int().min(1).max(100000),eventId:fk,status:z.enum(['Open','Closed']).default('Open'),notes:str}).strict(),
 shiftReservations:z.object({shiftId:id,constituentId:id,status:z.enum(['Reserved','Waitlisted','Cancelled']),notes:str}).strict(),
 constituents:z.object({name,email,phone:short,type:z.enum(['Individual','Business','Foundation','Alumni','Employee','Staff','Community partner']),household:short,parentId:fk,contacts:z.array(z.object({name,email,role:short}).strict()).max(50).default([]),segments:short,preference:z.enum(['Email','Phone','Post','Do not contact']).default('Email'),notes:str}).strict(),
 designations:z.object({name,school:short,parentId:fk,accountCode:short,description:str}).strict(),
 campaigns:z.object({name,type:z.enum(['Annual','Capital','Major gifts','Planned giving','Matching gifts','Peer-to-peer']),goal:cents,startDate:date,endDate:date,status:z.enum(['Active','Planned','Completed']),description:str}).strict(),
 gifts:z.object({constituentId:id,amount:cents.min(1),type:z.enum(['Cash','In-kind','Grant','Fee payment','Employee giving','Sponsorship']),method:z.enum(['Check','Cash','Credit card','ACH','Payroll','In-kind']),date,campaignId:fk,allocations:z.array(z.object({designationId:id,amount:cents.min(1)}).strict()).min(1).max(100),externalRef:short,notes:str,tribute:short,softCreditId:fk,pledge:short,pledgeId:fk,grantId:fk,giftKind:z.enum(['One-time','Recurring','Pledge fulfillment','Matching gift','Planned gift']).default('One-time')}).strict(),
 grants:z.object({name,funderId:fk,amount:cents,awardedAmount:cents.default(0),awardDate:date.nullable().optional().default(null),stage:z.enum(['Prospect','Preparing','Submitted','Awarded','Declined','Closed']),deadline:date,reportDue:date.nullable().optional().default(null),notes:str}).strict(),
 volunteers:z.object({constituentId:id,skills:short,shift:short,eventId:fk,hours:z.number().min(0).max(1e6).default(0),capacity:z.number().int().min(0).max(1e6).optional(),notes:str}).strict(),
 events:z.object({name,date,location:short,capacity:z.number().int().min(1).max(100000),ticketPrice:cents.default(0),sponsorGoal:cents.default(0),notes:str}).strict(),
 tasks:z.object({title:name,dueDate:date,owner:short,ownerId:fk,status:z.enum(['Open','In progress','Completed']),priority:z.enum(['Normal','High']).default('Normal'),constituentId:fk,eventId:fk,notes:str}).strict(),
 pledges:z.object({name,constituentId:id,amount:cents.min(1),startDate:date,installments:z.number().int().min(1).max(120),frequency:z.enum(['Monthly','Quarterly','Annual']),designationId:fk,campaignId:fk,status:z.enum(['Active','Paused','Cancelled']).default('Active'),notes:str}).strict(),
 reportViews:z.object({name,filters:z.object({report:z.enum(['Contributions by donor','Gifts by designation','Gift ledger','First-time donors','Donor follow-up','Volunteer hours','Grant pipeline','Soft-credit recognition','Organization rollup','Household rollup','Pledge balances','Volunteer time ledger','Grant reconciliation']),start:z.union([date,z.literal('')]).default(''),end:z.union([date,z.literal('')]).default(''),type:z.enum(['All','Cash','In-kind','Grant','Fee payment','Employee giving','Sponsorship']).default('All'),schoolYear:z.string().max(30).regex(/^(All|\d{4}|\d{4}[–-]\d{4})$/).default('All'),excludeFees:z.boolean().default(true),inactiveDays:z.number().int().min(1).max(3650).default(90)}).strict()}).strict(),
 evaluations:z.object({scenarioId:z.enum(['giving','pledges','recognition','grants','volunteers','events','stewardship','reporting','access','shifts','operations']),tester:name,result:z.enum(['Passed','Needs attention','Blocked']),severity:z.enum(['Low','Medium','High']).default('Medium'),actual:z.string().trim().min(1).max(8000),reproduction:str,notes:str}).strict(),
 communications:z.object({constituentId:fk,subject:name,channel:z.enum(['Email','Phone','Meeting','Post']),status:z.enum(['Draft','Logged']),date,body:str,notes:str}).strict()
};
const hash=v=>createHash('sha256').update(v).digest('hex');
const passwordHash=p=>{const salt=randomBytes(16).toString('hex');return salt+':'+scryptSync(p,salt,64).toString('hex');};
function verifyPassword(p,stored){try{const [s,h]=stored.split(':');const expected=Buffer.from(h,'hex');return timingSafeEqual(scryptSync(p,s,64),expected);}catch{return false;}}
class ApiError extends Error{constructor(status,message){super(message);this.status=status;}}
