 app.delete('/api/records/:collection/:id',csrf,write,(req,res)=>{transaction(()=>{const c=req.params.collection;if(!collections.includes(c))fail(404,'Unknown collection');if(c==='gifts')fail(403,'Financial records must be voided');if(c==='volunteerTime')fail(403,'Volunteer time entries cannot be deleted');if(c==='shiftReservations')fail(403,'Cancel reservations to preserve roster history');const r=get(c,req.params.id);reminders.validateDeletion(c,r);communicationWorkflowService.validateDeletion(c,r);peerFundraisingGuard.validateDeletion(c,r);hostedGivingService?.validateDeletion(c,r);if(c==='tasks')taskOwnership.validateDeletion(r);versionCheck(r,z.object({version:z.number().int().min(1)}).parse(req.body).version);financialCorrections.validateDeletion(c,r);for(const target of collections)for(const other of list(target)){if(target===c&&other.id===r.id)continue;const referenced=(c==='constituents'&&[other.constituentId,other.funderId,other.softCreditId,other.parentId,other.mergedInto,...(other.registrations||[]).map(x=>x.constituentId)].includes(r.id))||(c==='designations'&&(other.designationId===r.id||other.parentId===r.id||(other.allocations||[]).some(a=>a.designationId===r.id)))||(c==='campaigns'&&other.campaignId===r.id)||(c==='events'&&other.eventId===r.id)||(c==='grants'&&other.grantId===r.id)||(c==='pledges'&&other.pledgeId===r.id)||(c==='volunteerShifts'&&other.shiftId===r.id)||(c==='volunteers'&&other.volunteerId===r.id)||(c==='communications'&&other.acknowledgment?.communicationId===r.id);if(referenced)fail(409,'Record is referenced and cannot delete');}if(c==='events'&&r.registrations.length)fail(409,'Registered event cannot delete');fundraisingGuard?.validateMutation(c,r,null);eventGuard?.validateDeletion(c,r);eventHelperGuard?.validateDeletion(c,r);tributeGuard?.validateDeletion(c,r);grantGuard?.validateDeletion(c,r);db.prepare('DELETE FROM records WHERE collection=? AND id=?').run(c,r.id);audit(req.user,'delete',c,r.id);});res.json({ok:true});});
