  const record=transaction(()=>{const gift=get('gifts',req.params.id);versionCheck(gift,body.version);if(gift.status==='Voided')fail(409,'Voided gifts cannot change');const override=parseAssignedYear(body.schoolYear),at=now();const next={...gift,schoolYearOverride:override,schoolYearAssignment:{schoolYear:override,reason:body.reason,at,actorId:req.user.id,fiscalStartMonth:getSettings().fiscalStartMonth},version:gift.version+1,updatedAt:at};next.schoolYear=giftSchoolYear(next);put('gifts',next);audit(req.user,override===null?'reset_school_year':'reassign_school_year','gifts',gift.id,{previousSchoolYear:gift.schoolYear||giftSchoolYear(gift),previousOverride:gift.schoolYearOverride??null,schoolYear:next.schoolYear,override,reason:body.reason,fiscalStartMonth:getSettings().fiscalStartMonth});return next;});
