 app.post('/api/volunteers/:id/clock',csrf,write,(req,res)=>{const body=z.object({action:z.enum(['in','out']),version:z.number().int().min(1)}).strict().parse(req.body);const record=transaction(()=>{const r=get('volunteers',req.params.id);versionCheck(r,body.version);if(body.action==='in'){if(list('volunteers').some(v=>v.constituentId===r.constituentId&&v.clockIn))fail(409,'This constituent is already clocked in');r.clockIn=now();}else{if(!r.clockIn)fail(409,'Not clocked in');const endAt=now();if(Date.parse(endAt)<Date.parse(r.clockIn))fail(409,'Clock interval ends before it starts');const hours=Math.round((Date.parse(endAt)-Date.parse(r.clockIn))/3600000*1000000)/1000000;addTime(r,{startAt:r.clockIn,endAt,hours,source:'Clock',notes:''},req.user);r.hours=Math.round(list('volunteerTime').filter(t=>t.volunteerId===r.id).reduce((total,t)=>total+t.hours,0)*1000000)/1000000;r.clockIn=null;}return updateSpecial('volunteers',r,req.user,'clock_'+body.action);});res.json({record});});
 app.post('/api/volunteer-time/:id/correct',csrf,write,(req,res)=>{const body=z.object({version:z.number().int().min(1),hours:z.number().min(0).max(1e6),reason:z.string().trim().min(1).max(2000)}).strict().parse(req.body);const result=transaction(()=>{const record=get('volunteerTime',req.params.id);versionCheck(record,body.version);const volunteer=get('volunteers',record.volunteerId),previousHours=record.hours;record.originalHours=record.originalHours??previousHours;record.hours=body.hours;record.correctionReason=body.reason;record.correctedAt=now();record.version++;record.updatedAt=now();put('volunteerTime',record);audit(req.user,'correct_time','volunteerTime',record.id,{previousHours,hours:body.hours,originalHours:record.originalHours,reason:body.reason});volunteer.hours=Math.round(list('volunteerTime').filter(t=>t.volunteerId===volunteer.id).reduce((total,t)=>total+t.hours,0)*1000000)/1000000;updateSpecial('volunteers',volunteer,req.user,'reconcile_time');return {record,volunteer};});res.json(result);});
 app.post('/api/gifts/:id/acknowledge',csrf,write,(req,res)=>{const body=z.object({version:z.number().int().min(1),date,channel:z.enum(['Email','Phone','Meeting','Post']),notes:str,correspondence:z.object({preparationId:id,preparationDigest:z.string().length(64),confirmed:z.literal(true),reason:z.string().trim().min(1).max(2000)}).strict().optional()}).strict().parse(req.body);const result=transaction(()=>{const gift=get('gifts',req.params.id);versionCheck(gift,body.version);if(body.date>now().slice(0,10))fail(400,'Completed acknowledgment date cannot be in the future');if(gift.status==='Voided'||gift.type==='Fee payment')fail(409,'This gift cannot be acknowledged');if(gift.acknowledgment)fail(409,'Gift already acknowledged');if(body.date<gift.date)fail(400,'Completed acknowledgment cannot precede the gift date');const source=correspondenceService.validateAcknowledgmentSource(req.user,gift,body);const donor=get('constituents',gift.constituentId);if(donor.preference==='Do not contact')fail(403,'Do not contact: acknowledgment blocked');const communication=create('communications',{constituentId:donor.id,subject:'Manual gift acknowledgment',channel:body.channel,status:'Logged',date:body.date,body:body.notes,notes:'Manual completed action recorded; no message sent or receipt issued.'},req.user);communication.giftId=gift.id;if(source)communication.correspondence=source;put('communications',communication);gift.acknowledgment={date:body.date,channel:body.channel,notes:body.notes,communicationId:communication.id,at:now(),...(source?{correspondence:source}:{})};updateSpecial('gifts',gift,req.user,'acknowledge');if(source)correspondenceService.retainAcknowledgmentFulfillment(req.user,source,{gift,communication,date:body.date,channel:body.channel,reason:body.correspondence.reason});return {record:gift,communication};});res.json(result);});
 app.post('/api/events/:id/register',csrf,write,(req,res)=>{const body=z.object({constituentId:id,seating:short}).strict().parse(req.body);const record=transaction(()=>{const r=get('events',req.params.id);if(!exists('constituents',body.constituentId))fail(400,'Invalid constituent reference');eventGuard.validateRegistrationSeating(r.id,body.constituentId,body.seating);if(r.registrations.some(x=>x.constituentId===body.constituentId))fail(409,'Already registered');if(r.registrations.length>=r.capacity)fail(409,'Event at capacity');r.registrations.push({...body,checkedIn:false,registeredAt:now()});return updateSpecial('events',r,req.user,'register');});res.json({record});});
