 app.get('/api/readiness',admin,(req,res)=>{
  const data=Object.fromEntries(collections.map(c=>[c,list(c)]));
  const issues=[];
  for(const c of collections)for(const r of data[c]){
   if(!schemas[c])continue;
   const input=Object.fromEntries(Object.keys(schemas[c].shape).filter(k=>r[k]!==undefined).map(k=>[k,r[k]]));
   try{if(c==='gifts'&&r.status==='Voided'){for(const [target,key]of [['pledges','pledgeId'],['grants','grantId']])if(!exists(target,r[key]))fail(400,'Invalid '+target+' reference');input.pledgeId=null;input.grantId=null;}validate(c,input,r.id,r);}catch(e){issues.push({collection:c,recordId:r.id,label:r.name||r.title||r.subject||data.constituents.find(p=>p.id===r.constituentId)?.name||'Record',problem:e instanceof z.ZodError?'Record fields need review':e.message});}
  }
  const ledgerIssues=[];
  for(const entry of data.volunteerTime){const volunteer=data.volunteers.find(v=>v.id===entry.volunteerId);const validDates=entry.source==='Historical'?entry.startAt===null&&entry.endAt===null:entry.source==='Clock'&&Number.isFinite(Date.parse(entry.startAt))&&Number.isFinite(Date.parse(entry.endAt))&&Date.parse(entry.endAt)>=Date.parse(entry.startAt);
   if(!volunteer||entry.constituentId!==volunteer.constituentId||!exists('constituents',entry.constituentId)||!exists('events',entry.eventId)||!Number.isFinite(entry.hours)||entry.hours<0||!validDates)ledgerIssues.push({collection:'volunteerTime',recordId:entry.id,label:'Volunteer time entry',problem:'Review time fields, dated/historical distinction and original references'});
  }
  for(const volunteer of data.volunteers){const hours=Math.round(data.volunteerTime.filter(t=>t.volunteerId===volunteer.id).reduce((sum,t)=>sum+t.hours,0)*1e6)/1e6;if(hours!==volunteer.hours)ledgerIssues.push({collection:'volunteers',recordId:volunteer.id,label:data.constituents.find(p=>p.id===volunteer.constituentId)?.name||'Volunteer',problem:'Recorded hours do not reconcile to the time ledger'});}
  const checks=[{key:'time-ledger',label:'Volunteer time history and hour reconciliation',issues:ledgerIssues},{key:'records',label:'Record fields and connected references',issues},
   {key:'clocks',label:'One active volunteer clock per person',issues:data.volunteers.filter(v=>v.clockIn&&data.volunteers.some(o=>o.id!==v.id&&o.constituentId===v.constituentId&&o.clockIn)).map(v=>({collection:'volunteers',recordId:v.id,label:data.constituents.find(c=>c.id===v.constituentId)?.name||'Volunteer',problem:'Multiple active clocks for this person'}))}];
  res.json({checkedAt:now(),scope:'Local records only; no external provider or institutional approval checked',recordCount:Object.values(data).reduce((n,rows)=>n+rows.length,0),checks:checks.map(c=>({...c,status:c.issues.length?'Needs review':'Passed'}))});
 });
 app.get('/api/users',admin,(req,res)=>res.json({users:db.prepare('SELECT id,name,email,role,active,version FROM users ORDER BY name').all().map(accountView)}));
 app.post('/api/users',csrf,admin,(req,res)=>{const p=z.object({name,email:z.email().max(254).transform(x=>x.toLowerCase()),password:z.string().min(12).max(200),role:z.enum(['admin','staff','viewer','event-helper'])}).strict().parse(req.body);const user=transaction(()=>{if(db.prepare('SELECT 1 FROM users WHERE email=?').get(p.email))fail(409,'Email already exists');const u={id:randomUUID(),name:p.name,email:p.email,role:p.role,active:1,version:1};db.prepare('INSERT INTO users(id,name,email,role,password_hash) VALUES(?,?,?,?,?)').run(u.id,u.name,u.email,u.role,passwordHash(p.password));audit(req.user,'create_user','users',u.id,{role:u.role,active:true});return accountView(u);});res.status(201).json({user});});
 app.patch('/api/users/:id',csrf,admin,(req,res)=>{
  const body=z.object({version:z.number().int().min(1),role:z.enum(['admin','staff','viewer','event-helper']),active:z.boolean()}).strict().parse(req.body);
  const result=transaction(()=>{
   const previous=db.prepare('SELECT * FROM users WHERE id=?').get(req.params.id);
   if(!previous)fail(404,'Account not found');
   versionCheck(previous,body.version);
   if(previous.role===body.role&&Boolean(previous.active)===body.active)return {user:accountView(previous),sessionsRevoked:0};
   if(previous.active&&previous.role==='admin'&&(!body.active||body.role!=='admin')){
    const others=db.prepare("SELECT COUNT(*) AS count FROM users WHERE active=1 AND role='admin' AND id<>?").get(previous.id).count;
    if(!others)fail(409,'Keep at least one active administrator. Add another administrator before changing this account.');
   }
   db.prepare('UPDATE users SET role=?,active=?,version=version+1 WHERE id=?').run(body.role,Number(body.active),previous.id);
   const sessionsRevoked=db.prepare('DELETE FROM sessions WHERE user_id=?').run(previous.id).changes;
   db.prepare('DELETE FROM mfa_challenges WHERE user_id=?').run(previous.id);
   eventHelperGuard.retireAccountAssignments(req,previous,previous.version+1);
   audit(req.user,'change_access','users',previous.id,{previousRole:previous.role,role:body.role,previousActive:Boolean(previous.active),active:body.active,sessionsRevoked});
   return {user:accountView(db.prepare('SELECT * FROM users WHERE id=?').get(previous.id)),sessionsRevoked};
  });
  res.json(result);
 });
 app.patch('/api/settings',csrf,admin,(req,res)=>{const p=z.object({organizationName:name,fiscalStartMonth:z.number().int().min(1).max(12)}).strict().parse(req.body);transaction(()=>{db.prepare('UPDATE settings SET data=? WHERE id=1').run(JSON.stringify(p));for(const gift of list('gifts')){const override=gift.schoolYearOverride?formatAssignedYear(Number(gift.schoolYearOverride.slice(0,4)),p.fiscalStartMonth):null;const next={...gift,...(gift.schoolYearOverride?{schoolYearOverride:override}:{}),schoolYear:giftSchoolYear({...gift,schoolYearOverride:override}),version:gift.version+1,updatedAt:now()};put('gifts',next);if(gift.schoolYearOverride&&(gift.schoolYearOverride!==override||gift.schoolYear!==next.schoolYear))audit(req.user,'reformat_school_year','gifts',gift.id,{previousSchoolYear:gift.schoolYear,previousOverride:gift.schoolYearOverride,schoolYear:next.schoolYear,override,fiscalStartMonth:p.fiscalStartMonth});}audit(req.user,'update_settings',null,null);});res.json({settings:p});});
